pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BANK_SAFE c;

    function setUp() public {
        c = new BANK_SAFE();
    }

    function _run(uint256 m, uint256 d, uint256 a) internal {
        d = bound(d, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= d);
        vm.assume(m <= a && a <= d);
        try c.SetMinSum(m) {} catch { return; }
        try c.Initialized() {} catch { return; }
        try c.Deposit{value: d}() {} catch { return; }
        uint256 b0;
        try c.balances(address(this)) returns (uint256 __r) { b0 = __r; } catch { return; }
        uint e0 = address(c).balance;
        try c.Collect(a) {} catch { return; }
        assertTrue(c.balances(address(this)) + a == b0 && address(c).balance + a == e0);
    }

    function testFuzz_run(uint256 m, uint256 d, uint256 a) public {
        _run(m, d, a);
    }

    receive() external payable {}
}
